<label>Name</label><input name="name" required value="{{old('name',$product->name ?? '')}}"><label>Description</label><textarea name="description">{{old('description',$product->description ?? '')}}</textarea><label>Price USD</label><input type="number" step="0.01" name="price_usd" required value="{{old('price_usd',$product->price_usd ?? '')}}"><label>Stock</label><input type="number" name="stock" required value="{{old('stock',$product->stock ?? 0)}}"><label>Status</label><select name="status">@foreach(['available','coming_soon','out_of_stock','draft'] as $status)<option value="{{$status}}" @selected(old('status',$product->status ?? '')===$status)>{{ucwords(str_replace('_',' ',$status))}}</option>@endforeach</select>